def find_highest(scores):
    high = 0
    for i in range (len(scores)):
        if scores[i] > high:
            high = scores[i]
    return high
def find_lowest(scores):
    low = scores[0]
    for i in range (len(scores)):
        if scores[i] < low:
            low = scores[i]
    return low
def calculate_average(scores):
    average = 0
    for i in range (len(scores)):
        average = average + scores[i]
    average = average /len(scores)
    return average

